package br.com.bemdoar.controller;
import br.com.bemdoar.dto.*;import br.com.bemdoar.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/campanhas") public class CampanhaController{private final CampanhaService s;public CampanhaController(CampanhaService s){this.s=s;}@GetMapping public List<CampanhaResponse> listar(){return s.listar();}@GetMapping("/{id}")public CampanhaResponse buscar(@PathVariable Long id){return s.buscar(id);}@GetMapping("/{id}/necessidades")public List<NecessidadeResponse> necessidades(@PathVariable Long id){return s.buscar(id).necessidades();}
 @PostMapping @PreAuthorize("hasRole('ADMINISTRADOR')")public ResponseEntity<CampanhaResponse> criar(@Valid @RequestBody CampanhaRequest q){return ResponseEntity.status(201).body(s.criar(q));}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public CampanhaResponse editar(@PathVariable Long id,@Valid @RequestBody CampanhaRequest q){return s.editar(id,q);}@PatchMapping("/{id}/ativar")@PreAuthorize("hasRole('ADMINISTRADOR')")public CampanhaResponse ativar(@PathVariable Long id){return s.ativar(id);}@PatchMapping("/{id}/encerrar")@PreAuthorize("hasRole('ADMINISTRADOR')")public CampanhaResponse encerrar(@PathVariable Long id){return s.encerrar(id);}@PatchMapping("/{id}/cancelar")@PreAuthorize("hasRole('ADMINISTRADOR')")public CampanhaResponse cancelar(@PathVariable Long id,@RequestBody CancelamentoRequest q){return s.cancelar(id,q);}@PostMapping("/{id}/necessidades/{nid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public CampanhaResponse vincular(@PathVariable Long id,@PathVariable Long nid){return s.vincular(id,nid);}@DeleteMapping("/{id}/necessidades/{nid}")@PreAuthorize("hasRole('ADMINISTRADOR')")public CampanhaResponse desvincular(@PathVariable Long id,@PathVariable Long nid){return s.desvincular(id,nid);}}
